import { useState, useEffect, useRef } from "react";
import { Box, Button } from "@mui/material";

const THEMES = {
  dark: {
    "--main-bg": "#1b1b1b",
    "--primary-bg": "#333",
    "--light-bg": "gray",
    "--main-text": "#666",
    "--primary-text": "black",
    "--gold-hover": "#ab844e",
    "--white-text": "white",
    "--border-color": "#ccc",
    "--shadow-color": "rgba(0, 0, 0, 0.1)",
  },
  light: {
    "--main-bg": "#f5f5f5",
    "--primary-bg": "#ddd",
    "--light-bg": "#eee",
    "--main-text": "#444",
    "--primary-text": "#222",
    "--gold-hover": "#d4a15e",
    "--white-text": "#000",
    "--border-color": "#999",
    "--shadow-color": "rgba(0, 0, 0, 0.2)",
  },
  blue: {
    "--main-bg": "#1e3a8a",
    "--primary-bg": "#3b82f6",
    "--light-bg": "#93c5fd",
    "--main-text": "#e0f2fe",
    "--primary-text": "white",
    "--gold-hover": "#60a5fa",
    "--white-text": "#f0f9ff",
    "--border-color": "#2563eb",
    "--shadow-color": "rgba(30, 58, 138, 0.3)",
  },
};

const MangeLayout = () => {
  const colorInputRef = useRef(null);

  // Get the saved theme or use default
  const [selectedTheme, setSelectedTheme] = useState(() => {
    return localStorage.getItem("selectedTheme") || "dark";
  });

  useEffect(() => {
    applyTheme(THEMES[selectedTheme]); // Apply saved theme
  }, [selectedTheme]);

  const applyTheme = (theme) => {
    Object.keys(theme).forEach((key) => {
      document.documentElement.style.setProperty(key, theme[key]);
    });
  };

  const handleThemeChange = (themeName) => {
    setSelectedTheme(themeName);
    applyTheme(THEMES[themeName]);
    localStorage.setItem("selectedTheme", themeName); // Save theme in localStorage
  };

  return (
    <Box sx={{ textAlign: "center", mt: 3 }}>
      {/* Button to open color picker */}
      <Button
        variant="contained"
        onClick={() => colorInputRef.current.click()}
        sx={{ backgroundColor: THEMES[selectedTheme]["--primary-bg"], color: THEMES[selectedTheme]["--white-text"] }}
      >
        Open Full Color Palette
      </Button>

      {/* Hidden Color Picker Input */}
      <input
        type="color"
        ref={colorInputRef}
        style={{ display: "none" }}
        onChange={(e) => document.documentElement.style.setProperty("--main-bg", e.target.value)}
      />

      {/* Quick Theme Selection */}
      <Box sx={{ display: "flex", gap: 2, justifyContent: "center", mt: 2 }}>
        {Object.keys(THEMES).map((theme) => (
          <Box
            key={theme}
            onClick={() => handleThemeChange(theme)}
            sx={{
              width: 40,
              height: 40,
              borderRadius: "50%",
              backgroundColor: THEMES[theme]["--main-bg"],
              cursor: "pointer",
              border: selectedTheme === theme ? "3px solid white" : "2px solid #fff",
              transition: "transform 0.2s",
              "&:hover": { transform: "scale(1.2)" },
            }}
          />
        ))}
      </Box>
    </Box>
  );
};

export default MangeLayout;
